package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen1Test {

    private StringWriter out;
    private JsonWriter writer;

    @Before
    public void setUp() {
        out = new StringWriter();
        writer = new JsonWriter(out);
    }

    @Test
    public void testValue_Null() throws IOException {
        JsonWriter result = writer.value((Number) null);
        assertNull(result);
        assertEquals("null", out.toString());
    }

    @Test
    public void testValue_Integer() throws IOException {
        writer.value(123);
        assertEquals("123", out.toString());
    }

    @Test
    public void testValue_Double() throws IOException {
        writer.value(123.45);
        assertEquals("123.45", out.toString());
    }

    @Test
    public void testValue_Long() throws IOException {
        writer.value(9223372036854775807L);
        assertEquals("9223372036854775807", out.toString());
    }

    @Test
    public void testValue_Lenient_Infinity() throws IOException {
        writer.setLenient(true);
        writer.value(Double.POSITIVE_INFINITY);
        assertEquals("Infinity", out.toString());
    }

    @Test
    public void testValue_Lenient_NaN() throws IOException {
        writer.setLenient(true);
        writer.value(Double.NaN);
        assertEquals("NaN", out.toString());
    }

    @Test
    public void testValue_Lenient_NegativeInfinity() throws IOException {
        writer.setLenient(true);
        writer.value(Double.NEGATIVE_INFINITY);
        assertEquals("-Infinity", out.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NonLenient_Infinity_Throws() throws IOException {
        writer.setLenient(false);
        writer.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NonLenient_NaN_Throws() throws IOException {
        writer.setLenient(false);
        writer.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NonLenient_NegativeInfinity_Throws() throws IOException {
        writer.setLenient(false);
        writer.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValue_FluentInterface() throws IOException {
        writer.beginObject();
        writer.name("test");
        JsonWriter returnedWriter = writer.value(42);
        writer.endObject();

        assertEquals(writer, returnedWriter);
        assertEquals("{\"test\":42}", out.toString());
    }
}
